+        border-radius: 1.5rem;
+        box-shadow: var(--shadow);
+        padding: 2rem;
+      }
+
+      .eyebrow {
+        margin: 0 0 0.5rem;
+        color: var(--accent);
+        font-size: 0.875rem;
+        font-weight: 600;
+        letter-spacing: 0.04em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0 0 0.75rem;
+        font-size: clamp(1.5rem, 3vw, 2rem);
+        line-height: 1.2;
+      }
+
+      .description {
+        margin: 0 0 1.5rem;
+        color: var(--muted);
+        line-height: 1.5;
+      }
+
+      form {
+        display: grid;
+        gap: 1.25rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.5rem;
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        background: var(--surface-alt);
+      }
+
+      .checkbox-row {
+        display: flex;
+        gap: 0.75rem;
+        align-items: flex-start;
+      }
+
+      input[type="checkbox"] {
+        width: 1.125rem;
+        height: 1.125rem;
+        margin-top: 0.15rem;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.4;
+      }
+
+      .helper-text {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+        line-height: 1.5;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 0.9rem;
+        padding: 0.85rem 1.2rem;
+        background: linear-gradient(180deg, var(--accent) 0%, var(--accent-hover) 100%);
+        color: #fff;
+        font: inherit;
+        font-weight: 600;
+        cursor: pointer;
+        box-shadow: 0 10px 20px rgba(37, 99, 235, 0.25);
+      }
+
+      button:hover {
+        filter: brightness(1.03);
+      }
+
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .status {
+        margin: 0;
+        min-height: 1.5rem;
+        color: #0f766e;
+        font-weight: 600;
+      }
+
+      @media (max-width: 480px) {
+        .card {
+          padding: 1.5rem;
+          border-radius: 1.25rem;
+        }
+
+        .actions {
+          justify-content: stretch;
+        }
+
+        button {
+          width: 100%;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <div id="root"></div>
+
+    <script>
+      const h = (tag, attrs = {}, children = []) => {
+        const element = document.createElement(tag);
+        for (const [key, value] of Object.entries(attrs)) {
+          if (key === "className") {
+            element.className = value;
+          } else if (key.startsWith("on") && typeof value === "function") {
+            element.addEventListener(key.slice(2).toLowerCase(), value);
+          } else if (value !== false && value != null) {
+            element.setAttribute(key, value === true ? "" : String(value));
+          }
+        }
+        for (const child of children.flat()) {
+          element.append(child instanceof Node ? child : document.createTextNode(String(child)));
+        }
+        return element;
+      };
+
+      function ConsentField() {
+        const checkboxId = "terms-consent";
+        return h("div", { className: "form-field" }, [
+          h("div", { className: "checkbox-row" }, [
+            h("input", {
+              type: "checkbox",
+              id: checkboxId,
+              name: "consent",
+              required: true,
+              "aria-describedby": "consent-help"
+            }),
+            h("div", {}, [
+              h("label", { for: checkboxId }, ["I agree to the terms of use"]),
+              h("p", { id: "consent-help", className: "helper-text" }, [
+                "You must agree before continuing."
+              ])
+            ])
+          ])
+        ]);
+      }
+
+      function App() {
+        const statusId = "form-status";
+        const form = h("form", {
+          novalidate: false,
+          onsubmit: (event) => {
+            event.preventDefault();
+            const checkbox = form.querySelector("#terms-consent");
+            if (!checkbox.checkValidity()) {
+              checkbox.reportValidity();
+              return;
+            }
+            status.textContent = "Thanks — your consent has been submitted.";
+          }
+        }, [
+          h("p", { className: "eyebrow" }, ["Consent"]),
+          h("h1", {}, ["Agree to continue"]),
+          h("p", { className: "description" }, [
+            "Please confirm your agreement to the terms of use before submitting."
+          ]),
+          ConsentField(),
+          h("div", { className: "actions" }, [
+            h("button", { type: "submit" }, ["Submit"])
+          ]),
+          h("p", { className: "status", id: statusId, "aria-live": "polite" }, [""])
+        ]);
+
+        const status = form.querySelector("#" + statusId);
+        return h("main", { id: "main-content" }, [
+          h("section", { className: "card", "aria-labelledby": "page-title" }, [
+            form
+          ])
+        ]);
+      }
+
+      document.getElementById("root").append(App());
+      document.querySelector("h1").id = "page-title";
+    </script>
+  </body>
+</html>
*** End Patch
